// Fail fast on placeholder settings, BEFORE spending any API quota.
// The free WPScan tier allows 25 lookups a day; a run that dies halfway because
// notify_from was blank has burned quota the customer cannot get back.
const s = $json;
const errs = [];

if (!s.site_url || !/^https?:\/\//i.test(String(s.site_url)) || /example\.(com|org)/i.test(s.site_url)) {
  errs.push('site_url must be the full address of your WordPress site, e.g. https://yoursite.com');
}
if (!s.notify_email || /example\.com$/i.test(s.notify_email)) {
  errs.push('notify_email is still the placeholder - mail to example.com is accepted and discarded');
}
if (!s.notify_from || !String(s.notify_from).includes('@')) {
  errs.push('notify_from must be an address your SMTP credential is allowed to send as');
}
const max = Number(s.max_lookups_per_run);
if (!Number.isFinite(max) || max < 1) {
  errs.push('max_lookups_per_run must be a whole number, 1 or more');
}
// Optional, because a hardened WordPress does not publish its version anywhere.
// If it is set it must look like a version, or every core lookup 404s silently.
const core = String(s.wp_core_version || '').trim();
if (core && !/^\d+(\.\d+){0,3}$/.test(core)) {
  errs.push('wp_core_version must look like 6.9.4, or be left empty to skip core');
}
if (errs.length) throw new Error('Settings check failed:\n - ' + errs.join('\n - '));

return [{ json: { ...s, site_url: String(s.site_url).replace(/\/+$/, ''),
                  max_lookups_per_run: max, wp_core_version: core } }];

// Decide what to look up tonight, within the API budget.
//
// The free tier is 25 lookups a day and a real site needs far more than that -
// datadrifter.io alone has 38 active plugins. So this is deliberately NOT
// "scan everything": it spends the smaller of the remaining quota and the
// per-run cap, oldest-checked first, so every component is covered over a few
// days and the quota is never blown.
const s = $('Check your settings').first().json;

// Both nodes can return an array in one item or one item per element,
// depending on the HTTP node's settings. Handle both rather than assume.
function rows(nodeName) {
  const out = [];
  let items;
  try { items = $(nodeName).all(); } catch (e) { return out; }
  for (const i of items) {
    const j = i.json;
    if (Array.isArray(j)) out.push(...j);
    else if (j && typeof j === 'object' && Object.keys(j).length > 0) out.push(j);
  }
  return out;
}

const quota = $('Ask WPScan how much quota is left').first().json || {};
const remaining = Number(quota.requests_remaining);
const budget = Math.max(0, Math.min(s.max_lookups_per_run, Number.isFinite(remaining) ? remaining : 0));

// Last-checked times, so the rotation is fair rather than alphabetical.
const seen = {};
for (const r of rows('Read the scan history')) {
  if (r.component) seen[r.component] = r.last_checked || '';
}

const candidates = [];
if (s.wp_core_version) {
  candidates.push({ kind: 'core', slug: s.wp_core_version, version: s.wp_core_version,
                    name: 'WordPress core', active: true });
}
for (const t of rows('List the themes')) {
  if (!t.stylesheet) continue;
  candidates.push({ kind: 'theme', slug: t.stylesheet, version: String(t.version || ''),
                    name: (t.name && t.name.rendered) || t.stylesheet,
                    active: t.status === 'active' });
}
for (const p of rows('List the plugins')) {
  if (!p.plugin) continue;
  candidates.push({ kind: 'plugin', slug: String(p.plugin).split('/')[0],
                    version: String(p.version || ''), name: p.name || p.plugin,
                    active: p.status === 'active' });
}

// A component with no version cannot be judged against fixed_in, and reporting
// it as clean would be a lie. Carried through so the report can name it.
const unknownVersion = candidates.filter((c) => !c.version);
const scannable = candidates.filter((c) => c.version);

for (const c of scannable) {
  c.component = `${c.kind}:${c.slug}`;
  c.last_checked = seen[c.component] || '';
}
// Active things first, then oldest-checked. Never-checked sorts first because
// '' precedes any ISO timestamp.
scannable.sort((a, b) => (b.active === true) - (a.active === true)
                      || String(a.last_checked).localeCompare(String(b.last_checked)));

const chosen = scannable.slice(0, budget);
const meta = {
  total: candidates.length, scannable: scannable.length, budget,
  quota_remaining: Number.isFinite(remaining) ? remaining : null,
  quota_limit: quota.requests_limit ?? null,
  deferred: Math.max(0, scannable.length - chosen.length),
  unknown_version: unknownVersion.map((c) => `${c.kind}:${c.slug}`),
  core_checked: Boolean(s.wp_core_version),
};

if (!chosen.length) {
  // Emitting nothing here would stop the branch and the report would never be
  // sent - the exact failure that made three sibling runs look green while four
  // nodes never executed. Emit a sentinel instead and let the IF route it.
  return [{ json: { nothingToScan: true, meta } }];
}
return chosen.map((c) => ({ json: { ...c, meta } }));

// Decide whether THIS component's installed version is actually affected.
//
// This is the node the whole product rests on. The WPScan API returns every
// vulnerability ever recorded for a component - contact-form-7 returns 8, going
// back to a 2014 issue fixed in 3.5.3. A site running 6.1.7 is affected by none
// of them. Reporting the raw count would be a false alarm every single night,
// which is worse than no scanner: people stop reading it.
const item = $('One component at a time').first().json;
const raw = $input.first().json || {};

// The lookup node returns the full response so the status code is visible here.
// 404 means WPScan has no record of this component - completely normal for
// commercial or custom plugins and themes, and NOT the same as "clean".
// Anything else non-200 is a real problem and must reach the report: a scan
// that says "clean" because the API key expired is the worst possible outcome.
const status = Number(raw.statusCode ?? 200);
const resp = (raw.body !== undefined ? raw.body : raw) || {};

function base(extra) {
  return [{ json: {
    component: item.component, kind: item.kind, slug: item.slug,
    name: item.name, version: item.version, latest_version: null,
    last_checked: new Date().toISOString(),
    affected_count: 0, total_known: 0,
    findings: '[]', findings_list: [], ...extra,
  } }];
}

if (status === 404) return base({ not_in_database: true });
if (status !== 200) return base({ lookup_error: `HTTP ${status}` });

// Compare dotted versions numerically. '1.10' is NEWER than '1.9', which a
// string compare gets backwards - and getting it backwards here means either a
// missed vulnerability or a false alarm.
function cmp(a, b) {
  const pa = String(a).split(/[.\-+_]/).map((x) => parseInt(x, 10) || 0);
  const pb = String(b).split(/[.\-+_]/).map((x) => parseInt(x, 10) || 0);
  const n = Math.max(pa.length, pb.length);
  for (let i = 0; i < n; i++) {
    const d = (pa[i] || 0) - (pb[i] || 0);
    if (d !== 0) return d > 0 ? 1 : -1;
  }
  return 0;
}

// Keyed by slug (or by version for core), so take the first key rather than
// assuming it matches what we asked for.
const key = Object.keys(resp)[0];
const info = (key && resp[key]) || {};
const all = Array.isArray(info.vulnerabilities) ? info.vulnerabilities : [];

const affected = all.filter((v) => {
  if (v.introduced_in && cmp(item.version, v.introduced_in) < 0) return false;
  if (!v.fixed_in) return true;              // never fixed - still affected
  return cmp(item.version, v.fixed_in) < 0;  // fixed later than what is installed
});

// The free tier returns cvss: null, so there is no CVSS to report. This banding
// is DataDrifter's, derived from vuln_type, and the report says so. Presenting
// it as a CVSS score would be inventing a number.
//
// Every type WPScan has actually returned is listed EXPLICITLY below, the minor
// ones included, because the fall-through used to be `|| 'low'` - which asserted
// a severity for types nobody had ever assessed. WPScan keeps adding types, so
// an unrecognised one is now 'unknown' and the report prints it as such. For a
// security scanner the dangerous error is the quiet one: not knowing has to look
// like not knowing, never like "minor".
const BAND = {
  RCE: 'critical', SQLI: 'critical', AUTHBYPASS: 'critical', PRIVESC: 'critical',
  UPLOAD: 'critical', RFI: 'critical', XXE: 'critical',
  // Object injection in PHP is deserialization of untrusted data - RCE by
  // another name. It fell through to 'low' until execution 59 showed it doing so.
  'OBJECT INJECTION': 'critical',
  XSS: 'high', CSRF: 'high', LFI: 'high', SSRF: 'high', IDOR: 'high', BYPASS: 'high',
  // The same classes as LFI and BYPASS, which were already high. Leaving these to
  // fall through was an inconsistency, not a judgement.
  TRAVERSAL: 'high', INJECTION: 'high',
  'NO AUTHORISATION': 'high', 'INCORRECT AUTHORISATION': 'high',
  REDIRECT: 'medium', DOS: 'medium',
  // Judged minor ON PURPOSE, and written down so that it is a decision rather
  // than a default.
  'SENSITIVE DATA DISCLOSURE': 'low',
};
const findings = affected.map((v) => ({
  title: v.title, type: v.vuln_type || 'UNKNOWN',
  severity: BAND[String(v.vuln_type || '').toUpperCase().trim()] || 'unknown',
  fixed_in: v.fixed_in || null,
  cve: ((v.references || {}).cve || [])[0] || null,
}));

return [{ json: {
  component: item.component, kind: item.kind, slug: item.slug,
  name: item.name, version: item.version,
  latest_version: info.latest_version || null,
  last_checked: new Date().toISOString(),
  affected_count: findings.length,
  total_known: all.length,
  findings: JSON.stringify(findings),
  findings_list: findings,
} }];

// Build the report.
//
// Counts come from every run index, not the last: inside a splitInBatches loop
// a node runs once per component, and a bare .all() would report only the final
// one. The sibling template emailed "0 backed up" for a run that backed up 2
// before this was understood.
function allRuns(nodeName) {
  const out = [];
  for (let i = 0; ; i++) {
    let items;
    try { items = $(nodeName).all(0, i); } catch (e) { break; }
    if (!items || !items.length) break;
    out.push(...items.map((x) => x.json));
  }
  return out;
}

const s = $('Check your settings').first().json;
const looked = allRuns('Match against your version');
const plan = allRuns('Plan the lookups');
const meta = (plan[0] || {}).meta || {};

// A lookup that returned an answer, a lookup that found no record, and a lookup
// that failed are three different outcomes. Only the first is "checked".
// Execution 51 collapsed all three into one number and called the result clean.
const errored = looked.filter((c) => c.lookup_error);
const notInDb = looked.filter((c) => c.not_in_database && !c.lookup_error);
const checked = looked.filter((c) => !c.not_in_database && !c.lookup_error);

const withVulns = checked.filter((c) => c.affected_count > 0);
// 'unknown' is a real band, not a gap: it means WPScan reported a vuln_type
// this template has not assessed. It is listed FIRST after the real severities
// so it cannot be mistaken for the tail of the list, and it counts towards
// totalFindings so it forces the email like any other finding.
const order = ['critical', 'high', 'unknown', 'medium', 'low'];
const tally = { critical: 0, high: 0, unknown: 0, medium: 0, low: 0 };
for (const c of withVulns) {
  for (const f of (c.findings_list || [])) tally[f.severity] = (tally[f.severity] || 0) + 1;
}
const totalFindings = order.reduce((n, k) => n + tally[k], 0);

const lines = [];
lines.push(`Site: ${s.site_url}`);
lines.push(`Components checked this run: ${checked.length} of ${meta.scannable ?? '?'}`);
lines.push(`API quota: ${meta.quota_remaining ?? '?'} of ${meta.quota_limit ?? '?'} remaining before this run`);
if (meta.deferred) {
  lines.push(`Deferred to the next run (quota): ${meta.deferred}`);
}
// A run that checked NOTHING is not a clean run, and must never share wording
// with one. Found 2026-08-27 by the operator: an exhausted quota produced
// "clean scan (0 checked)" over a site nothing had looked at. The per-component
// version of this bug was fixed the day before; this is the whole-run version,
// which neither that fix nor its tests could see.
const nothingChecked = checked.length === 0;
let nothingReason = 'nothing was available to check';
if (meta.quota_remaining === 0) {
  nothingReason = 'the WPScan daily quota is exhausted';
} else if (meta.budget === 0) {
  nothingReason = 'max_lookups_per_run is set to 0';
} else if (notInDb.length) {
  nothingReason = 'every component looked up is absent from the vulnerability database';
} else if (!meta.scannable) {
  nothingReason = 'no component reported a version that could be checked';
}

lines.push('');
if (nothingChecked) {
  lines.push(`NOTHING WAS CHECKED THIS RUN - ${nothingReason}.`);
  lines.push('');
  lines.push('This report says NOTHING about your site. Not one component was compared');
  lines.push('against the vulnerability database, so this is not a clean result and must');
  lines.push('not be read as one.');
} else if (!totalFindings) {
  lines.push(`No known vulnerabilities affecting the ${checked.length} version(s) that were checked.`);
} else {
  lines.push(`VULNERABILITIES AFFECTING YOUR INSTALLED VERSIONS: ${totalFindings}`);
  lines.push(order.map((k) => `${k}: ${tally[k]}`).join('   '));
  lines.push('');
  for (const c of withVulns) {
    lines.push(`${c.kind} ${c.name} ${c.version}` +
      (c.latest_version ? `  (latest ${c.latest_version})` : ''));
    for (const f of c.findings_list) {
      lines.push(`  [${f.severity.toUpperCase()}] ${f.title}`);
      lines.push(`      type ${f.type}` +
        (f.fixed_in ? `, fixed in ${f.fixed_in}` : ', NO FIX AVAILABLE') +
        (f.cve ? `, ${f.cve}` : ''));
    }
    lines.push('');
  }
}

// A lookup that FAILED is the loudest thing in this report. Everything below it
// is unreliable, so it goes above the ordinary caveats and it forces the email.
if (errored.length) {
  lines.push(`LOOKUP FAILED FOR ${errored.length} COMPONENT(S) - THIS SCAN IS INCOMPLETE:`);
  for (const c of errored) {
    lines.push(`  - ${c.name} ${c.version} (${c.lookup_error})`);
  }
  lines.push('  A 401 means the WPScan API token is wrong or expired; a 429 means the');
  lines.push('  daily quota is spent. Until this is fixed, treat the result as unknown.');
  lines.push('');
}

// Say what was NOT checked. A scan report that quietly omits things reads as
// reassurance, which is the worst possible failure for a security product.
const caveats = [];
if (!meta.core_checked) {
  caveats.push('WordPress CORE WAS NOT CHECKED - wp_core_version is empty in Scan settings. '
    + 'A hardened WordPress does not publish its version, so it cannot be detected automatically.');
}
if (notInDb.length) {
  // Commercial and custom plugins are simply absent from WPScan. That is not a
  // clean bill of health and must never be printed as one.
  caveats.push(`NOT IN THE VULNERABILITY DATABASE, so nothing is known either way - `
    + `this is NOT the same as clean: `
    + notInDb.map((c) => `${c.name} ${c.version}`).join(', '));
}
if (meta.deferred) {
  caveats.push(`${meta.deferred} component(s) were not checked tonight because the API quota `
    + 'would not cover them. They are first in line on the next run.');
}
if ((meta.unknown_version || []).length) {
  caveats.push('No version reported, so not checkable: ' + meta.unknown_version.join(', '));
}
if (caveats.length) {
  lines.push('NOT CHECKED THIS RUN:');
  for (const c of caveats) lines.push(`  - ${c}`);
  lines.push('');
}
lines.push('Severity is DataDrifter\'s banding of the vulnerability type. The free WPScan');
lines.push('tier does not return CVSS scores, so no CVSS figure is shown or implied.');

// The subject must distinguish a clean scan from a broken one at a glance, in a
// mail list, without opening it.
let subject;
if (errored.length) {
  subject = `WordPress security: SCAN INCOMPLETE - ${errored.length} lookup(s) failed`;
} else if (totalFindings) {
  subject = `WordPress security: ${totalFindings} issue(s) on ${s.site_url.replace(/^https?:\/\//, '')}`;
} else if (nothingChecked) {
  // "nothing was checked" and "nothing is wrong" are opposite messages. They
  // shared a subject line until 2026-08-27.
  subject = `WordPress security: NOTHING WAS CHECKED - ${nothingReason}`;
} else {
  // The coverage fraction belongs in the subject, not only in the body. On the
  // free tier a run routinely checks 4 of 42, and "clean scan (4 checked)" reads
  // like a whole-site all-clear in a mail list.
  subject = `WordPress security: clean scan (${checked.length} of ${meta.scannable ?? '?'} checked`
    + (notInDb.length ? `, ${notInDb.length} not in database` : '') + ')';
}

return [{ json: {
  subject, body: lines.join('\n'),
  findings: totalFindings, checked: checked.length,
  not_in_database: notInDb.length, lookup_errors: errored.length,
  critical: tally.critical, high: tally.high, medium: tally.medium, low: tally.low,
  unknown: tally.unknown,
  // A failed lookup always emails. Silence would mean the scanner broke and
  // said nothing, which is the failure this whole product exists to prevent.
  nothing_checked: nothingChecked,
  // A run that checked nothing always emails. Staying silent would let a site
  // whose component count permanently exceeds the free tier look healthy for
  // ever, which is the failure mode this whole product exists to prevent.
  send: errored.length > 0 || nothingChecked || totalFindings > 0
        || s.alert_only_on_findings !== true,
} }];
